--
-- Trades in this part: restaurant
--
-- Re-runnable. Creates 2 tables. Verification at the end.

BEGIN;

-- ── restaurant ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.partner_restaurant_profiles (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  service_id  UUID REFERENCES public.vendor_services(id) ON DELETE CASCADE,
  trade_id    TEXT NOT NULL DEFAULT 'restaurant' CHECK (trade_id = 'restaurant'),
  schema_version INTEGER NOT NULL DEFAULT 1,
  restaurant_name              TEXT,
  cuisines                     TEXT[],
  diet                         TEXT,
  dining_modes                 TEXT[],
  meal_formats                 TEXT[],
  events                       TEXT[],
  photos                       TEXT[],
  seating_capacity             NUMERIC,
  private_room_capacity        NUMERIC,
  delivery_radius_km           NUMERIC,
  min_order_guests             NUMERIC,
  open_hours                   TEXT,
  facilities                   TEXT[],
  alcohol                      BOOLEAN,
  advance_notice_hours         NUMERIC,
  outside_cake                 BOOLEAN,
  decor_allowed                BOOLEAN,
  music_allowed                BOOLEAN,
  max_hours                    NUMERIC,
  source_specs JSONB,
  backfilled_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_restaurant_profile_service
  ON public.partner_restaurant_profiles (service_id) WHERE service_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_restaurant_profile_vendor ON public.partner_restaurant_profiles (vendor_id);

COMMENT ON COLUMN public.partner_restaurant_profiles.restaurant_name IS
  'Restaurant name [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.cuisines IS
  'Cuisines you serve [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.diet IS
  'Food you serve [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.dining_modes IS
  'How can a celebration book you? [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.meal_formats IS
  'What can you offer a group? [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.events IS
  'Celebrations you host';
COMMENT ON COLUMN public.partner_restaurant_profiles.photos IS
  'Photos of the restaurant and the food [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.seating_capacity IS
  'Seats in the restaurant [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.private_room_capacity IS
  'Private room / hall capacity';
COMMENT ON COLUMN public.partner_restaurant_profiles.delivery_radius_km IS
  'Bulk orders delivered within';
COMMENT ON COLUMN public.partner_restaurant_profiles.min_order_guests IS
  'Minimum guests for a bulk order';
COMMENT ON COLUMN public.partner_restaurant_profiles.open_hours IS
  'Opening hours';
COMMENT ON COLUMN public.partner_restaurant_profiles.facilities IS
  'Facilities';
COMMENT ON COLUMN public.partner_restaurant_profiles.alcohol IS
  'Alcohol served (licensed)';
COMMENT ON COLUMN public.partner_restaurant_profiles.advance_notice_hours IS
  'Notice you need for a group booking [required]';
COMMENT ON COLUMN public.partner_restaurant_profiles.outside_cake IS
  'Guests may bring their own cake';
COMMENT ON COLUMN public.partner_restaurant_profiles.decor_allowed IS
  'Guests may decorate the table or room';
COMMENT ON COLUMN public.partner_restaurant_profiles.music_allowed IS
  'Guests may play their own music';
COMMENT ON COLUMN public.partner_restaurant_profiles.max_hours IS
  'Longest a group may hold the table or room';

ALTER TABLE public.partner_restaurant_profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_restaurant_profiles_owner ON public.partner_restaurant_profiles;
CREATE POLICY partner_restaurant_profiles_owner ON public.partner_restaurant_profiles FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_restaurant_profiles.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_restaurant_profiles.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_restaurant_profiles_operator ON public.partner_restaurant_profiles;
CREATE POLICY partner_restaurant_profiles_operator ON public.partner_restaurant_profiles FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

-- restaurant: repeating catalogue items (packages)
CREATE TABLE IF NOT EXISTS public.partner_restaurant_items (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  service_id  UUID REFERENCES public.vendor_services(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL DEFAULT 0,
  name                         TEXT,
  format                       TEXT,
  diet                         TEXT,
  courses                      NUMERIC,
  includes                     TEXT,
  price_per_person             BIGINT,
  min_guests                   NUMERIC,
  max_guests                   NUMERIC,
  photos                       TEXT[],
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_restaurant_items_service ON public.partner_restaurant_items (service_id, position);

ALTER TABLE public.partner_restaurant_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_restaurant_items_owner ON public.partner_restaurant_items;
CREATE POLICY partner_restaurant_items_owner ON public.partner_restaurant_items FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_restaurant_items.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_restaurant_items.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_restaurant_items_operator ON public.partner_restaurant_items;
CREATE POLICY partner_restaurant_items_operator ON public.partner_restaurant_items FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

COMMIT;

-- ── verify ───────────────────────────────────────────────────────
-- Expect 2 rows.
SELECT table_name, (SELECT count(*) FROM information_schema.columns c
         WHERE c.table_schema = 'public' AND c.table_name = t.table_name) AS columns
  FROM information_schema.tables t
 WHERE table_schema = 'public' AND table_name IN ('partner_restaurant_profiles', 'partner_restaurant_items')
 ORDER BY table_name;
